shell_commands:
node --input-type=module -e "
import {createChatOrchestrator} from './src/orchestration/chatOrchestrator.ts';
import {PromptBuilder} from './src/infrastructure/builders/promptBuilder.ts';

const promptBuilder = new PromptBuilder({identity: 'test'});
const provider = {
  async *sendMessage() { throw 'string rejection'; },
  async generateStructured() { return {}; }
};
let onErrorCalled = false;
const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {
  hooks: {
    onError: async () => { onErrorCalled = true; }
  }
});
try {
  await orchestrator.processMessage({sessionId: 's', userId: 'u', entries: [{role: 'user', content: 'hi', timestamp: ''}]});
} catch (e) {
  console.log('caught rejection:', e, 'onErrorCalled:', onErrorCalled);
}
"

